cards.styles:
:host {
  display: block !important;
  width: 86px !important;
  min-width: 86px !important;
  max-width: 86px !important;
  margin: 0 auto !important;
  --bubble-button-main-background-color: rgba(0,0,0,0.06);
  --bubble-button-background-color: transparent;
  --bubble-button-box-shadow: none;
  --bubble-button-border-radius: 16px;
}
ha-card {
  width: 86px !important;
  height: 86px !important;
  box-sizing: border-box !important;
  margin: 0 !important;
  padding: 0 !important;
  border-radius: 16px !important;
  border: 1px solid rgba(140,210,230,0.16) !important;
  background: linear-gradient(
    315deg,
    rgba(38,72,85,0.75) 0%,
    rgba(15,32,45,0.90) 100%
  ) !important;
  box-shadow:
    0 6px 18px rgba(0,0,0,0.22),
    inset 0 1px 0 rgba(255,255,255,0.06) !important;
  transition: transform 160ms ease;
  -webkit-tap-highlight-color: transparent;
}
.bubble-button-card-container {
  width: 100% !important;
  height: 86px !important;
  min-height: 86px !important;
  box-sizing: border-box !important;
  padding: 0 !important;
  background: rgba(0,0,0,0.06) !important;
  border: 1px solid rgba(185,210,225,0.14) !important;
  border-radius: 16px !important;
  box-shadow: none !important;
  transition: background-color 160ms ease, border-color 160ms ease;
}
.bubble-background {
  background: transparent !important;
}
.bubble-wrapper {
  justify-content: center !important;
  align-items: center !important;
  padding: 0 !important;
  background: transparent !important;
}
.bubble-content-container {
  display: contents !important;
}
.bubble-name-container,
.bubble-sub-button-container {
  display: none !important;
}
.bubble-icon-container {
  width: 64px !important;
  height: 64px !important;
  min-width: 64px !important;
  min-height: 64px !important;
  flex: 0 0 64px !important;
  margin: 0 !important;
  border-radius: 12px !important;
  background: transparent !important;
  box-shadow: none !important;
}
.bubble-icon {
  --mdc-icon-size: 58px !important;
  opacity: 1 !important;
  color: #00CED1 !important;
}
@media (hover: hover) {
  .bubble-button-card-container:hover {
    background: rgba(185,210,225,0.10) !important;
    border-color: rgba(185,210,225,0.24) !important;
  }
}
ha-card:active {
  transform: scale(0.95);
}
@media (prefers-reduced-motion: reduce) {
  ha-card,
  .bubble-button-card-container {
    transition: none !important;
  }
  ha-card:active {
    transform: none !important;
  }
}

